import sys
from collections import defaultdict

def main():
    input = sys.stdin.read().split()
    N = int(input[0])
    X = int(input[1])
    D = int(input[2])

    if D == 0:
        if X == 0:
            print(1)
        else:
            print(N + 1)
        return

    ranges = defaultdict(list)

    for m in range(N + 1):
        min_k = m * (m - 1) // 2
        max_k = m * (2 * N - m - 1) // 2
        a_m = X * m + D * min_k
        R = a_m + D * (max_k - min_k)
        if a_m <= R:
            r = (X * m) % D
            ranges[r].append((a_m, R))

    total = 0
    for r in ranges:
        ranges_list = sorted(ranges[r], key=lambda x: x[0])
        merged = []
        for a, b in ranges_list:
            if not merged:
                merged.append((a, b))
            else:
                last_a, last_b = merged[-1]
                if a <= last_b:
                    new_b = max(last_b, b)
                    merged[-1] = (last_a, new_b)
                else:
                    merged.append((a, b))
        for a, b in merged:
            count = ((b - a) // D) + 1
            total += count
    print(total)

if __name__ == "__main__":
    main()
