MOD = 998244353

def main():
    import sys
    input = sys.stdin.read
    N, M, K = map(int, input().split())

    if N == 0:
        print(0)
        return

    x = M - 1
    max_n = N - 1

    # Precompute factorial and inverse factorial
    fact = [1] * (max_n + 1)
    for i in range(1, max_n + 1):
        fact[i] = fact[i-1] * i % MOD

    inv_fact = [1] * (max_n + 1)
    inv_fact[max_n] = pow(fact[max_n], MOD-2, MOD)
    for i in range(max_n - 1, -1, -1):
        inv_fact[i] = inv_fact[i+1] * (i+1) % MOD

    def comb(n, k):
        if k < 0 or k > n:
            return 0
        return fact[n] * inv_fact[k] % MOD * inv_fact[n - k] % MOD

    # Precompute powers of x
    pow_x = [1] * (max_n + 1)
    for i in range(1, max_n + 1):
        pow_x[i] = pow_x[i-1] * x % MOD

    # Compute prefix sums
    prefix = [0] * (max_n + 1)
    for k in range(max_n + 1):
        c = comb(max_n, k)
        term = c * pow_x[k] % MOD
        if k == 0:
            prefix[k] = term
        else:
            prefix[k] = (prefix[k-1] + term) % MOD

    l = max(0, N - K - 1)
    u = N - 1

    if l > u:
        total = 0
    else:
        if l == 0:
            total = prefix[u]
        else:
            total = (prefix[u] - prefix[l-1]) % MOD

    ans = total * M % MOD
    print(ans)

if __name__ == "__main__":
    main()
