import sys

def main():
    H, W = map(int, sys.stdin.readline().split())
    A = [list(map(int, sys.stdin.readline().split())) for _ in range(H)]
    B = [list(map(int, sys.stdin.readline().split())) for _ in range(H)]

    c = [[A[i][j] - B[i][j] for j in range(W)] for i in range(H)]

    max_sum = (H + W - 1) * 80
    shift = max_sum
    mask_size = 2 * max_sum + 1

    # Initialize dp with False
    dp = [[[False] * mask_size for _ in range(W)] for _ in range(H)]

    # Initialize the first cell
    c00 = c[0][0]
    for s in [c00, -c00]:
        if -max_sum <= s <= max_sum:
            dp[0][0][s + shift] = True

    # Process other cells
    for i in range(H):
        for j in range(W):
            if i == 0 and j == 0:
                continue
            current = [False] * mask_size
            if i > 0:
                for k in range(mask_size):
                    if dp[i-1][j][k]:
                        s_prev = k - shift
                        new_s1 = s_prev + c[i][j]
                        new_s2 = s_prev - c[i][j]
                        if -max_sum <= new_s1 <= max_sum:
                            current[new_s1 + shift] = True
                        if -max_sum <= new_s2 <= max_sum:
                            current[new_s2 + shift] = True
            if j > 0:
                for k in range(mask_size):
                    if dp[i][j-1][k]:
                        s_prev = k - shift
                        new_s1 = s_prev + c[i][j]
                        new_s2 = s_prev - c[i][j]
                        if -max_sum <= new_s1 <= max_sum:
                            current[new_s1 + shift] = True
                        if -max_sum <= new_s2 <= max_sum:
                            current[new_s2 + shift] = True
