import sys

def main():
    input = sys.stdin.read().split()
    N = int(input[0])
    K = int(input[1])
    H = list(map(int, input[2:2+N]))

    # Initialize dp: dp[i][k] is a dictionary of {value: min_sum}
    dp = [[{} for _ in range(K+1)] for _ in range(N+1)]
    dp[0][0][0] = 0

    for i in range(1, N+1):
        for k_prev in range(K+1):
            if not dp[i-1][k_prev]:
                continue
            for value_prev in dp[i-1][k_prev]:
                current_sum = dp[i-1][k_prev][value_prev]
                # Case 1: do not change the current column
                new_value = H[i-1]
                new_sum = current_sum + max(0, new_value - value_prev)
                if new_value in dp[i][k_prev]:
                    if new_sum < dp[i][k_prev][new_value]:
                        dp[i][k_prev][new_value] = new_sum
                else:
                    dp[i][k_prev][new_value] = new_sum
                # Case 2: change the current column
                new_value_change = value_prev
                new_sum_change = current_sum
                if k_prev + 1 <= K:
                    if new_value_change in dp[i][k_prev + 1]:
                        if new_sum_change < dp[i][k_prev + 1][new_value_change]:
                            dp[i][k_prev + 1][new_value_change] = new_sum_change
                    else:
                        dp[i][k_prev + 1][new_value_change] = new_sum_change

    min_total = float('inf')
    for k in range(K+1):
        if dp[N][k]:
            current_min = min(dp[N][k].values())
            if current_min < min_total:
                min_total = current_min
    print(min_total)

if __name__ == "__main__":
