        for k in range(K+1):
            # Iterate over all possible previous values
            for prev_val in dp[i-1][k]:
                current_val = H[i]
                # Case 1: not modify current column
                contribution = max(0, current_val - prev_val)
                new_sum = dp[i-1][k][prev_val] + contribution
                if current_val in dp[i][k]:
                    if new_sum < dp[i][k][current_val]:
                        dp[i][k][current_val] = new_sum
                else:
                    dp[i][k][current_val] = new_sum
                # Case 2: modify current column
                if k + 1 <= K:
                    new_sum_modified = dp[i-1][k][prev_val] + 0
                    if prev_val in dp[i][k+1]:
                        if new_sum_modified < dp[i][k+1][prev_val]:
                            dp[i][k+1][prev_val] = new_sum_modified
                    else:
                        dp[i][k+1][prev_val] = new_sum_modified

    # Find the minimum sum
    min_total = float('inf')
    for k in range(K+1):
        for val in dp[N-1][k]:
            current_sum = dp[N-1][k][val]
            total = current_sum + H[0]
            if total < min_total:
