import sys

def main():
    N = int(sys.stdin.readline())
    # Generate primes up to N using sieve of Eratosthenes
    sieve = [True] * (N + 1)
    sieve[0] = sieve[1] = False
    for i in range(2, int(N**0.5) + 1):
        if sieve[i]:
            for j in range(i * i, N + 1, i):
                sieve[j] = False
    primes = [i for i, is_prime in enumerate(sieve) if is_prime]

    # Calculate exponents of each prime in N!
    exponents = []
    for p in primes:
        exp = 0
        power = p
        while power <= N:
            exp += N // power
            power *= p
        exponents.append(exp)

    # Backtracking to count valid combinations
    total = 0

    def backtrack(index, product):
        nonlocal total
        if index == len(exponents):
            if product == 75:
                total += 1
            return
        e = exponents[index]
        # Generate possible values for this prime
        possible_values = []
        for value in [1, 3, 5, 15, 25, 75]:
            if (value - 1) <= e:
                possible_values.append(value)
        for value in possible_values:
            if product * value > 75:
                continue
            backtrack(index + 1, product * value)

    backtrack(0, 1)
    print(total)

