import sys

def sieve(n):
    if n < 2:
        return []
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(n ** 0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, n + 1, i):
                is_prime[j] = False
    primes = [i for i, val in enumerate(is_prime) if val]
    return primes

def legendre(n, p):
    total = 0
    power = p
    while power <= n:
        total += n // power
        power *= p
    return total

def main():
    N = int(sys.stdin.readline())
