import math

def is_colinear(a, b, c):
    return (b[0] - a[0]) * (c[1] - a[1]) == (b[1] - a[1]) * (c[0] - a[0])

def compute_circumcircle(a, b, c):
    x1, y1 = a
    x2, y2 = b
    x3, y3 = c
    A1 = 2 * (x2 - x1)
    B1 = 2 * (y2 - y1)
    C1 = x2**2 + y2**2 - x1**2 - y1**2
    A2 = 2 * (x3 - x1)
    B2 = 2 * (y3 - y1)
    C2 = x3**2 + y3**2 - x1**2 - y1**2
    D = A1 * B2 - A2 * B1
    if D == 0:
        return None
    Ox = (B2 * C1 - B1 * C2) / D
    Oy = (A1 * C2 - A2 * C1) / D
    r = math.hypot(Ox - x1, Oy - y1)
    return (Ox, Oy, r)

def is_valid_circle(points, cx, cy, r):
    for (x, y) in points:
        dx = x - cx
        dy = y - cy
        dist_sq = dx * dx + dy * dy
        if dist_sq > r * r + 1e-8:
            return False
    return True

def main():
    import sys
    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx])
    idx += 1
    points = []
    for _ in range(N):
        x = int(input[idx])
        y = int(input[idx+1])
        points.append((x, y))
        idx += 2
    min_radius = float('inf')
    for i in range(N):
        for j in range(i+1, N):
            x1, y1 = points[i]
            x2, y2 = points[j]
            cx = (x1 + x2) / 2.0
            cy = (y1 + y2) / 2.0
            r = math.hypot(x1 - x2, y1 - y2) / 2.0
            if is_valid_circle(points, cx, cy, r):
                if r < min_radius:
                    min_radius = r
    for i in range(N):
        for j in range(i+1, N):
            for k in range(j+1, N):
                a = points[i]
                b = points[j]
                c = points[k]
                if is_colinear(a, b, c):
                    continue
                circle = compute_circumcircle(a, b, c)
                if circle is not None:
                    cx, cy, r = circle
                    if is_valid_circle(points, cx, cy, r):
                        if r < min_radius:
                            min_radius = r
    print("{0:.20f}".format(min_radius))

if __name__ == "__main__":
    main()
