MOD = 10**9 + 7

def main():
    import sys
    input = sys.stdin.read
    N, K = map(int, input().split())
    M = N + 1

    def compute_sum(a, b):
        return (b * (b + 1) // 2) - ((a - 1) * a // 2)

    def compute_sum_squares(a, b):
        return (b * (b + 1) * (2 * b + 1) // 6) - ((a - 1) * a * (2 * (a - 1) + 1) // 6)

    sum_m = compute_sum(K, M)
    sum_m2 = compute_sum_squares(K, M)
    sum_1 = M - K + 1

    total = ( (N + 1) * sum_m - sum_m2 + sum_1 ) % MOD
    print(total)

if __name__ == "__main__":
    main()
